"""Turn the cursor frame PNGs (make_cursor_frames.py) into a C header for binkw32.dll.

  python make_cursor_inc.py <frames dir> <out.inc>

Writes kCurFrames<size>[24][size*size] as 0xAARRGGBB words (straight alpha, top-down rows), sizes 32/40/48/64.
"""
import os, sys
from PIL import Image

src, out = sys.argv[1], sys.argv[2]
sizes = (32, 40, 48, 64)
lines = ['// Generated by work/tools/make_cursor_inc.py from work/mods/mainmenu/cursor_frames (make_cursor_frames.py).',
         '// The dadmod wheel cursor: 24 rotation frames per size, hotspot at 0,0. Do not edit by hand.',
         'namespace curframes {',
         'static const int kFrames = 24;']
for s in sizes:
    lines.append('static const unsigned int kCur%d[24][%d] = {' % (s, s * s))
    for i in range(24):
        im = Image.open(os.path.join(src, 'cur_%d_%02d.png' % (s, i))).convert('RGBA')
        px = list(im.getdata())
        words = ['0x%08X' % ((a << 24) | (r << 16) | (g << 8) | b) for (r, g, b, a) in px]
        body = []
        for k in range(0, len(words), 16):
            body.append(','.join(words[k:k + 16]))
        lines.append('{' + ',\n'.join(body) + '},')
    lines.append('};')
lines.append('}  // namespace curframes')
open(out, 'w', newline='\n').write('\n'.join(lines) + '\n')
print('wrote', out, os.path.getsize(out), 'bytes')
